pub fn spawn(&mut self) -> io::Result<Child> {
    // On two lines to circumvent a mutable borrow check failure.
    let child = self.std.spawn()?;
    self.build_child(child)
}

pub fn spawn<F>(&self, future: F) -> JoinHandle<F::Output>
where
    F: Future + Send + 'static,
    F::Output: Send + 'static,
{
    let fut_size = mem::size_of::<F>();
    if fut_size > BOX_FUTURE_THRESHOLD {
        self.spawn_named(Box::pin(future), SpawnMeta::new_unnamed(fut_size))
    } else {
        self.spawn_named(future, SpawnMeta::new_unnamed(fut_size))
    }
}

pub fn spawn<F>(&self, future: F) -> JoinHandle<F::Output>
where
    F: Future + Send + 'static,
    F::Output: Send + 'static,
{
    let fut_size = mem::size_of::<F>();
    if fut_size > BOX_FUTURE_THRESHOLD {
        self.handle
            .spawn_named(Box::pin(future), SpawnMeta::new_unnamed(fut_size))
    } else {
        self.handle
            .spawn_named(future, SpawnMeta::new_unnamed(fut_size))
    }
}

fn spawn<F>(&self, future: F, meta: SpawnMeta<'_>) -> JoinHandle<F::Output>
where
    F: Future + 'static,
    F::Output: 'static,
{
    let id = crate::runtime::task::Id::next();
    let future = crate::util::trace::task(future, "local", meta, id.as_u64());

    // Safety: called from the thread that owns the `LocalSet`
    let (handle, notified) = {
        self.shared.local_state.assert_called_from_owner_thread();
        self.shared.local_state.owned.bind(
            future,
            self.shared.clone(),
            id,
            SpawnLocation::capture(),
        )
    };

    if let Some(notified) = notified {
        self.shared.schedule(notified);
    }

    handle
}

pub fn spawn<Fut>(self, future: Fut) -> io::Result<JoinHandle<Fut::Output>>
where
    Fut: Future + Send + 'static,
    Fut::Output: Send + 'static,
{
    let fut_size = mem::size_of::<Fut>();
    Ok(if fut_size > BOX_FUTURE_THRESHOLD {
        super::spawn::spawn_inner(Box::pin(future), SpawnMeta::new(self.name, fut_size))
    } else {
        super::spawn::spawn_inner(future, SpawnMeta::new(self.name, fut_size))
    })
}

pub(super) fn spawn_blocking<F, R>(f: F) -> JoinHandle<R>
where
    F: FnOnce() -> R + Send + 'static,
    R: Send + 'static,
{
    let (tx, rx) = oneshot::channel();
    let task = Box::new(move || {
        let _ = tx.send(f());
    });

    QUEUE.with(|cell| cell.borrow_mut().push_back(task));

    JoinHandle { rx }
}

pub(crate) fn spawn(&self, meta: &TaskMeta<'_>) {
    if let Some(f) = self.task_spawn_callback.as_ref() {
        f(meta)
    }
}

fn spawn<T>(&self, future: T) -> JoinHandle<T::Output>
where
    T: 'static + Send + Future,
    T::Output: 'static + Send,
{
    let (handle, notified) =
        self.0
            .owned
            .bind(future, self.clone(), Id::next(), SpawnLocation::capture());

    if let Some(notified) = notified {
        self.schedule(notified);
    }

    handle
}

pub fn spawn_with(
    &mut self,
    with: impl FnOnce(&mut StdCommand) -> io::Result<StdChild>,
) -> io::Result<Child> {
    // On two lines to circumvent a mutable borrow check failure.
    let child = with(&mut self.std)?;
    self.build_child(child)
}
